changeSet.sql:

ALTER TABLE [integration].[ExecutionAssetTypeError]  DROP  CONSTRAINT if exists [FK_IntegrationExecutionAssetTypeError_IntegrationExecutionAssetType]
GO
ALTER TABLE [integration].[ExecutionAssetTypeLog]  DROP CONSTRAINT if exists [FK_IntegrationExecutionAssetTypeLog_IntegrationExecutionAssetType]
GO

if not exists (select 1 from sys.indexes where name = 'PK_IntegrationExecutionAssetType' and [type] = 1)
begin
	ALTER TABLE [integration].[ExecutionAssetType] DROP  CONSTRAINT if exists[PK_IntegrationExecutionAssetType];

	ALTER TABLE [integration].[ExecutionAssetType] ADD  CONSTRAINT PK_IntegrationExecutionAssetType PRIMARY KEY CLUSTERED 
	(
		[ExecutionID] DESC,
		[SynchedAssetTypeID] ASC
	)WITH (STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ONLINE = OFF) ON [PRIMARY];
end

if not exists (select 1 from sys.objects where name = 'FK_IntegrationExecutionAssetTypeError_IntegrationExecutionAssetType')
begin
	ALTER TABLE [integration].[ExecutionAssetTypeError]  WITH NOCHECK ADD  CONSTRAINT [FK_IntegrationExecutionAssetTypeError_IntegrationExecutionAssetType] FOREIGN KEY([ExecutionID], [SynchedAssetTypeID])
	REFERENCES [integration].[ExecutionAssetType] ([ExecutionID], [SynchedAssetTypeID])
	ON DELETE CASCADE;

	ALTER TABLE [integration].[ExecutionAssetTypeError] CHECK CONSTRAINT [FK_IntegrationExecutionAssetTypeError_IntegrationExecutionAssetType];

end

if not exists (select 1 from sys.objects where name = 'FK_IntegrationExecutionAssetTypeLog_IntegrationExecutionAssetType')
begin
	ALTER TABLE [integration].[ExecutionAssetTypeLog]  WITH NOCHECK ADD  CONSTRAINT [FK_IntegrationExecutionAssetTypeLog_IntegrationExecutionAssetType] FOREIGN KEY([ExecutionID], [SynchedAssetTypeID])
	REFERENCES [integration].[ExecutionAssetType] ([ExecutionID], [SynchedAssetTypeID])
	ON DELETE CASCADE;

	ALTER TABLE [integration].[ExecutionAssetTypeLog] CHECK CONSTRAINT [FK_IntegrationExecutionAssetTypeLog_IntegrationExecutionAssetType];
end
